import 'dart:convert';
import 'dart:io';

import 'package:crypto/crypto.dart';

/// Pins the codec and transitive Core algorithm sources into artifact keys.
/// --check is read-only and is required before reusing generated graph packs.
void main(List<String> args) {
  final package = File.fromUri(Platform.script).parent.parent;
  final library = Directory('${package.path}/lib');
  const outputPath = 'navigation/terrain_graph_artifact_revision.dart';
  final digest = navigationBuildRevision(library);
  final rendered =
      '// Generated by tool/update_navigation_revision.dart. Do not edit.\n'
      'const terrainGraphArtifactBuildRevision =\n'
      "    '$digest';\n";
  final output = File('${library.path}/$outputPath');
  if (args.contains('--check')) {
    if (!output.existsSync() ||
        output.readAsStringSync().replaceAll('\r\n', '\n') != rendered) {
      stderr.writeln(
        'Navigation build revision is stale. Run packages/runner_core/tool/update_navigation_revision.dart.',
      );
      exitCode = 1;
      return;
    }
  } else {
    output.writeAsStringSync(rendered);
  }
  stdout.writeln('Navigation build revision $digest.');
}

/// Recomputes source identity without trusting the generated revision file.
String navigationBuildRevision(Directory library) {
  const outputPath = 'navigation/terrain_graph_artifact_revision.dart';
  final pending = [
    'navigation/terrain_surface_graph_builder.dart',
    'navigation/terrain_surface_extractor.dart',
    'navigation/terrain_graph_artifact.dart',
  ];
  final sources = <String, String>{};
  final imports = RegExp(r'''(?:import|export|part)\s+['"]([^'"]+)['"]''');
  while (pending.isNotEmpty) {
    final relative = pending.removeLast();
    if (relative == outputPath || sources.containsKey(relative)) continue;
    final file = File.fromUri(library.uri.resolve(relative));
    final source = file.readAsStringSync().replaceAll('\r\n', '\n');
    sources[relative] = source;
    for (final match in imports.allMatches(source)) {
      final target = match[1]!;
      if (target.contains(':')) continue;
      final uri = Uri.parse(relative).resolve(target).normalizePath();
      if (uri.path.startsWith('../')) {
        throw StateError('Graph dependency escaped Core.');
      }
      pending.add(uri.path);
    }
  }
  final names = sources.keys.toList()..sort();
  final digest = sha256
      .convert(
        utf8.encode(
          jsonEncode([
            for (final name in names) [name, sources[name]],
          ]),
        ),
      )
      .toString();
  return digest;
}

/// Release producers run inside the source checkout, including compiled Docker
/// producers. Refuse to reuse artifacts if the executable or revision is stale.
void requireCurrentNavigationBuildRevision(String compiledRevision) {
  var directory = Directory.current.absolute;
  while (true) {
    final library = Directory('${directory.path}/packages/runner_core/lib');
    if (library.existsSync()) {
      if (navigationBuildRevision(library) != compiledRevision) {
        throw StateError(
          'Navigation revision is stale. Regenerate it and rebuild the producer before preparing artifacts.',
        );
      }
      return;
    }
    final parent = directory.parent;
    if (parent.path == directory.path) {
      throw StateError(
        'Run navigation preparation from inside the source checkout.',
      );
    }
    directory = parent;
  }
}
